import { useState, useRef, useEffect, lazy, Suspense } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import Page from '../shared/components/Page';
import PeekCard from '../shared/components/PeekCard';

// Lazy load time slip scanner
const TimeslipScanner = lazy(() => import('../shared/components/TimeslipScanner'));
import EnvironmentForm from '../shared/components/EnvironmentForm';
import { simulate } from '../workerBridge';
import { completeRun, type CompletionResult } from '../domain/quarter/completion';
import { createModel, update } from '../domain/learning/model';
import { extractFeatures } from '../domain/learning/features';
import { getModel, saveModel } from '../state/models';
import { storage } from '../state/storage';
import { useSubscription } from '../domain/config/useSubscription';
import { DEFAULT_ENV } from '../domain/schemas/env.schema';
import { parseCsv, mapWeatherRow, csvToObjects } from '../shared/utils/csvImport';
import { loadVehicles, type VehicleLite } from '../state/vehicles';
import { RoundTypes, type RunRecordV1 } from '../domain/schemas/run.schema';
import { calculateMOV, formatMOV, describeRaceOutcome } from '../domain/physics/calculations/marginOfVictory';
import type { RaceLength } from '../domain/config/raceLengths';
import type { Env } from '../domain/schemas/env.schema';
import type { PredictResult, PredictRequest } from '../domain/quarter/types';
import { fromVehicleToVB6Fixture } from '../dev/vb6/fromVehicle';
import { fixtureToSimInputs } from '../domain/physics/vb6/fixtures';

function Log() {
  const navigate = useNavigate();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const { runLimit, canSaveRun, tierInfo, features: tierFeatures } = useSubscription();

  // Vehicles list
  const [vehicles, setVehicles] = useState<VehicleLite[]>([]);
  
  // Section A: Run Context
  const [selectedVehicleId, setSelectedVehicleId] = useState('');
  const [raceLength, setRaceLength] = useState<RaceLength>('QUARTER');
  const [env, setEnv] = useState<Env>(DEFAULT_ENV);
  
  // Load vehicles on mount
  useEffect(() => {
    loadVehicles().then(v => {
      setVehicles(v);
      if (v.length > 0) {
        setSelectedVehicleId(v[0].id);
        setRaceLength(v[0].defaultRaceLength);
      }
    });
  }, []);
  
  // Get selected vehicle object
  const selectedVehicle = vehicles.find(v => v.id === selectedVehicleId) ?? null;
  const [baselineRequest, setBaselineRequest] = useState<PredictRequest | null>(null);
  const [baselineResult, setBaselineResult] = useState<PredictResult | null>(null);
  const [baselineLoading, setBaselineLoading] = useState(false);
  const [baselineError, setBaselineError] = useState<string | null>(null);
  const [features, setFeatures] = useState<number[] | null>(null);

  // Section B: Run Completion
  const [splitDistance, setSplitDistance] = useState<number>(660);
  const [splitTime, setSplitTime] = useState('');
  const [splitMph, setSplitMph] = useState('');
  const [completionResult, setCompletionResult] = useState<CompletionResult | null>(null);
  const [completionError, setCompletionError] = useState<string | null>(null);

  // Section C: Actual Result & Save
  const [actualET, setActualET] = useState('');
  const [actualMPH, setActualMPH] = useState('');
  const [notes, setNotes] = useState('');
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState<string | null>(null);
  
  // Run context fields (like Crew Chief)
  const [runDate, setRunDate] = useState(new Date().toISOString().split('T')[0]);
  const [runTime, setRunTime] = useState(new Date().toTimeString().slice(0, 5));
  const [round, setRound] = useState('T1');
  const [lane, setLane] = useState<'left' | 'right'>('left');
  const [reactionTime, setReactionTime] = useState('');
  const [dialIn, setDialIn] = useState('');
  
  // Timing splits
  const [sixtyFt, setSixtyFt] = useState('');
  const [threeThirtyFt, setThreeThirtyFt] = useState('');
  const [eighthET, setEighthET] = useState('');
  const [eighthMPH, setEighthMPH] = useState('');
  const [thousandFt, setThousandFt] = useState('');
  
  // Opponent Information
  const [opponentName, setOpponentName] = useState('');
  const [opponentDialIn, setOpponentDialIn] = useState('');
  const [opponentRT, setOpponentRT] = useState('');
  const [opponentET, setOpponentET] = useState('');
  const [opponentMPH, setOpponentMPH] = useState('');
  
  // Time Slip Scanner
  const [showScanner, setShowScanner] = useState(false);
  
  // Handle import from time slip scanner
  const handleTimeslipImport = (data: {
    user: {
      reactionTime?: number;
      sixtyFt?: number;
      threeThirtyFt?: number;
      eighthMileET?: number;
      eighthMileMPH?: number;
      thousandFt?: number;
      quarterMileET?: number;
      quarterMileMPH?: number;
      dialIn?: number;
    };
    opponent: {
      name?: string;
      reactionTime?: number;
      et?: number;
      mph?: number;
      dialIn?: number;
    };
    raceInfo: {
      date?: string;
      time?: string;
      trackName?: string;
      round?: string;
      runNumber?: number;
      userWon?: boolean | null;
      margin?: number;
    };
  }) => {
    // Import user timing data
    if (data.user.reactionTime) setReactionTime(data.user.reactionTime.toString());
    if (data.user.dialIn) setDialIn(data.user.dialIn.toString());
    if (data.user.sixtyFt) setSixtyFt(data.user.sixtyFt.toString());
    if (data.user.threeThirtyFt) setThreeThirtyFt(data.user.threeThirtyFt.toString());
    if (data.user.eighthMileET) setEighthET(data.user.eighthMileET.toString());
    if (data.user.eighthMileMPH) setEighthMPH(data.user.eighthMileMPH.toString());
    if (data.user.thousandFt) setThousandFt(data.user.thousandFt.toString());
    
    // Set actual ET/MPH based on race length
    if (raceLength === 'QUARTER') {
      if (data.user.quarterMileET) setActualET(data.user.quarterMileET.toString());
      if (data.user.quarterMileMPH) setActualMPH(data.user.quarterMileMPH.toString());
    } else {
      if (data.user.eighthMileET) setActualET(data.user.eighthMileET.toString());
      if (data.user.eighthMileMPH) setActualMPH(data.user.eighthMileMPH.toString());
    }
    
    // Import opponent data
    if (data.opponent.name) setOpponentName(data.opponent.name);
    if (data.opponent.reactionTime) setOpponentRT(data.opponent.reactionTime.toString());
    if (data.opponent.et) setOpponentET(data.opponent.et.toString());
    if (data.opponent.mph) setOpponentMPH(data.opponent.mph.toString());
    if (data.opponent.dialIn) setOpponentDialIn(data.opponent.dialIn.toString());
    
    // Import race info
    if (data.raceInfo.date) setRunDate(data.raceInfo.date);
    if (data.raceInfo.time) setRunTime(data.raceInfo.time);
    if (data.raceInfo.trackName) {
      setNotes(prev => prev ? `${prev}\nTrack: ${data.raceInfo.trackName}` : `Track: ${data.raceInfo.trackName}`);
    }
  };

  const handleImportWeatherCsv = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    try {
      const parsed = await parseCsv(file);
      const objects = csvToObjects(parsed);
      
      if (objects.length === 0) {
        alert('CSV file has no data rows');
        return;
      }

      // Try to map first row
      const mappedEnv = mapWeatherRow(objects[0]);
      
      if (mappedEnv) {
        setEnv(mappedEnv);
        alert(`✓ Weather data imported from CSV`);
      } else {
        alert('Couldn\'t detect required columns (elevation, temperature, barometer, humidity)');
      }
    } catch (error) {
      console.error('Failed to import CSV:', error);
      alert('Failed to parse CSV file');
    } finally {
      // Reset file input
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    }
  };

  const handleComputeBaseline = async () => {
    setBaselineError(null);
    setBaselineResult(null);
    setFeatures(null);
    setCompletionResult(null);

    if (!selectedVehicle) {
      setBaselineError('Please select a vehicle');
      return;
    }

    setBaselineLoading(true);

    try {
      // Use the selected vehicle for baseline calculation
      const vehicle = selectedVehicle;

      // Convert vehicle to VB6 fixture format and run simulation
      // This uses the same VB6Exact physics as the ET Sim
      // Force QuarterJr mode for non-Pro users
      const vb6Fixture = fromVehicleToVB6Fixture(vehicle as any, { 
        forceQuarterJr: !tierFeatures.quarterProFields 
      });
      const simInputs = fixtureToSimInputs(vb6Fixture, raceLength);
      
      // Override with current environment
      // VB6 Quarter Jr default: trackTemp = temperature + 30 when not specified
      const tempF = env.temperatureF ?? 75;
      simInputs.env = {
        elevation: env.elevation ?? 0,
        barometerInHg: env.barometerInHg ?? 29.92,
        temperatureF: tempF,
        humidityPct: env.humidityPct ?? 50,
        windMph: env.windMph ?? 0,
        windAngleDeg: env.windAngleDeg ?? 0,
        trackTempF: env.trackTempF ?? (tempF + 30),
        tractionIndex: env.tractionIndex ?? 5,
      };
      
      const simResult = await simulate('VB6Exact', simInputs);
      
      // Convert sim result to PredictResult format for compatibility
      const result: PredictResult = {
        baseET_s: simResult.et_s,
        baseMPH: simResult.mph,
        timeslip: simResult.traces?.map((t: any) => ({
          d_ft: t.s_ft,
          t_s: t.t_s,
          v_mph: t.v_mph,
        })) || [],
        factors: [],
      };
      
      const req: PredictRequest = { vehicle, env, raceLength };
      setBaselineRequest(req);
      setBaselineResult(result);

      // Extract features for learning
      const extracted = extractFeatures(req, result);
      setFeatures(extracted.x);

      setBaselineLoading(false);
    } catch (err) {
      setBaselineError(err instanceof Error ? err.message : 'Failed to compute baseline');
      setBaselineLoading(false);
    }
  };

  const handleCompleteRun = () => {
    setCompletionError(null);
    setCompletionResult(null);

    if (!baselineResult) {
      setCompletionError('Compute baseline first');
      return;
    }

    if (!splitTime) {
      setCompletionError('Split time is required');
      return;
    }

    if (!baselineRequest) {
      setCompletionError('Compute baseline first');
      return;
    }

    try {
      const req = baselineRequest;

      const anchor = {
        d_ft: splitDistance,
        t_s: parseFloat(splitTime),
        mph: splitMph ? parseFloat(splitMph) : undefined,
      };

      const result = completeRun(req, [anchor]);
      setCompletionResult(result);
    } catch (err) {
      setCompletionError(err instanceof Error ? err.message : 'Failed to complete run');
    }
  };

  const handleSaveRun = async () => {
    setSaveError(null);

    if (!baselineResult) {
      setSaveError('Compute baseline first');
      return;
    }

    if (!actualET) {
      setSaveError('Actual ET is required');
      return;
    }

    // Check runs limit
    const existingRuns = await storage.loadRuns();
    if (!canSaveRun(existingRuns.length)) {
      setSaveError(`Run limit reached (${runLimit} runs on ${tierInfo.name} tier). Upgrade to save more runs.`);
      return;
    }

    setSaving(true);

    try {
      const actualETValue = parseFloat(actualET);
      const actualMPHValue = actualMPH ? parseFloat(actualMPH) : undefined;

      // Update learning model
      if (features) {
        const observedError = actualETValue - baselineResult.baseET_s;
        
        const m0 = getModel(selectedVehicleId) ?? createModel(features.length);
        const m1 = update(m0, features, observedError);
        saveModel(selectedVehicleId, m1);
      }

      // Build and save run record
      // Build opponent info if provided
      const opponent = opponentName || opponentET ? {
        name: opponentName || undefined,
        dialIn: opponentDialIn ? parseFloat(opponentDialIn) : undefined,
        reactionTime: opponentRT ? parseFloat(opponentRT) : undefined,
        et: opponentET ? parseFloat(opponentET) : undefined,
        mph: opponentMPH ? parseFloat(opponentMPH) : undefined,
      } : undefined;

      const run: RunRecordV1 = {
        id: crypto.randomUUID(),
        createdAt: Date.now(),
        vehicleId: selectedVehicleId,
        raceLength,
        env,
        // Run context
        runDate,
        runTime,
        round,
        lane,
        reactionTime: reactionTime ? parseFloat(reactionTime) : undefined,
        dialIn: dialIn ? parseFloat(dialIn) : undefined,
        // Timing splits
        sixtyFt: sixtyFt ? parseFloat(sixtyFt) : undefined,
        threeThirtyFt: threeThirtyFt ? parseFloat(threeThirtyFt) : undefined,
        // Timing data from actual results
        quarterMileET: raceLength === 'QUARTER' ? actualETValue : undefined,
        quarterMileMPH: raceLength === 'QUARTER' ? actualMPHValue : undefined,
        eighthMileET: raceLength === 'EIGHTH' ? actualETValue : (eighthET ? parseFloat(eighthET) : undefined),
        eighthMileMPH: raceLength === 'EIGHTH' ? actualMPHValue : (eighthMPH ? parseFloat(eighthMPH) : undefined),
        thousandFt: thousandFt ? parseFloat(thousandFt) : undefined,
        // Prediction
        prediction: {
          et_s: baselineResult.baseET_s,
          mph: baselineResult.baseMPH,
        },
        outcome: {
          slipET_s: actualETValue,
          slipMPH: actualMPHValue,
        },
        increments: baselineResult.timeslip,
        notes: notes.trim() || undefined,
        // Opponent
        opponent,
      };

      await storage.saveRun(run);

      // Show success toast and navigate
      alert('✓ Run saved successfully! Model updated.');
      navigate('/history');
    } catch (err) {
      setSaveError(err instanceof Error ? err.message : 'Failed to save run');
      setSaving(false);
    }
  };

  // Available splits based on subscription tier features
  let availableSplits: number[] = [];
  if (tierFeatures.runCompletion) {
    // Full access: all splits except finish line
    availableSplits = raceLength === 'EIGHTH' ? [60, 330] : [60, 330, 660, 1000];
  } else if (tierFeatures.basicSim) {
    // Basic access: 60' only
    availableSplits = [60];
  }

  return (
    <Page title="Log Run">
      {/* Time Slip Scanner Modal */}
      <Suspense fallback={null}>
        <TimeslipScanner
          isOpen={showScanner}
          onClose={() => setShowScanner(false)}
          onImport={handleTimeslipImport}
        />
      </Suspense>
      
      {/* Quick Actions Bar */}
      <div className="card mb-4" style={{ padding: '12px 16px' }}>
        <div style={{ display: 'flex', gap: '12px', alignItems: 'center', flexWrap: 'wrap' }}>
          <button
            className="btn"
            onClick={() => setShowScanner(true)}
            style={{ 
              display: 'flex', 
              alignItems: 'center', 
              gap: '8px',
              backgroundColor: 'var(--color-accent)',
              padding: '10px 16px',
            }}
          >
            📸 Scan Time Slip
          </button>
          <span style={{ fontSize: '0.875rem', color: 'var(--color-text-muted)' }}>
            Take a photo of your time slip to auto-fill all timing data
          </span>
        </div>
      </div>
      
      {/* Section A: Run Context */}
      <div className="card mb-6">
        <h2 className="mb-4" style={{ fontSize: '1.25rem', color: 'var(--color-text)' }}>
          A) Run Context
        </h2>

        {baselineError && (
          <div className="error mb-4">
            <p style={{ margin: 0 }}>{baselineError}</p>
          </div>
        )}

        <div className="grid grid-2 gap-4 mb-4">
          <div>
            <label className="label" htmlFor="vehicle">
              Select Vehicle *
            </label>
            {vehicles.length === 0 ? (
              <div style={{ padding: 'var(--space-3)', color: 'var(--color-muted)' }}>
                No vehicles yet. <Link to="/vehicles" style={{ color: 'var(--color-primary)' }}>Create one first</Link>
              </div>
            ) : (
              <select
                id="vehicle"
                className="input"
                value={selectedVehicleId}
                onChange={(e) => {
                  setSelectedVehicleId(e.target.value);
                  const v = vehicles.find(v => v.id === e.target.value);
                  if (v) setRaceLength(v.defaultRaceLength);
                }}
                style={{ cursor: 'pointer' }}
              >
                {vehicles.map((v) => (
                  <option key={v.id} value={v.id}>
                    {v.name}
                  </option>
                ))}
              </select>
            )}
            {selectedVehicle && (
              <div className="text-muted" style={{ fontSize: '0.8rem', marginTop: 'var(--space-2)' }}>
                {selectedVehicle.weightLb} lb • {selectedVehicle.powerHP} HP • {selectedVehicle.tireDiaIn}" tire
              </div>
            )}
          </div>

          <div>
            <label className="label">Race Length *</label>
            <div className="radio-group">
              <label className="radio-label">
                <input
                  type="radio"
                  name="raceLength"
                  value="EIGHTH"
                  checked={raceLength === 'EIGHTH'}
                  onChange={(e) => setRaceLength(e.target.value as RaceLength)}
                />
                <span>1/8 Mile</span>
              </label>
              <label className="radio-label">
                <input
                  type="radio"
                  name="raceLength"
                  value="QUARTER"
                  checked={raceLength === 'QUARTER'}
                  onChange={(e) => setRaceLength(e.target.value as RaceLength)}
                />
                <span>1/4 Mile</span>
              </label>
            </div>
          </div>
        </div>

        {/* Run Details (like Crew Chief) */}
        <div className="grid grid-2 gap-4 mb-4" style={{ gridTemplateColumns: 'repeat(4, 1fr)' }}>
          <div>
            <label className="label">Date</label>
            <input
              type="date"
              className="input"
              value={runDate}
              onChange={(e) => setRunDate(e.target.value)}
            />
          </div>
          <div>
            <label className="label">Time</label>
            <input
              type="time"
              className="input"
              value={runTime}
              onChange={(e) => setRunTime(e.target.value)}
            />
          </div>
          <div>
            <label className="label">Round</label>
            <select
              className="input"
              value={round}
              onChange={(e) => setRound(e.target.value)}
            >
              {RoundTypes.map(r => (
                <option key={r} value={r}>{r}</option>
              ))}
            </select>
          </div>
          <div>
            <label className="label">Lane</label>
            <div className="radio-group" style={{ marginTop: '0.5rem' }}>
              <label className="radio-label">
                <input type="radio" name="lane" value="left" checked={lane === 'left'} onChange={() => setLane('left')} />
                <span>L</span>
              </label>
              <label className="radio-label">
                <input type="radio" name="lane" value="right" checked={lane === 'right'} onChange={() => setLane('right')} />
                <span>R</span>
              </label>
            </div>
          </div>
        </div>

        <div className="grid grid-2 gap-4 mb-4">
          <div>
            <label className="label">Reaction Time</label>
            <input
              type="number"
              step="0.001"
              className="input"
              value={reactionTime}
              onChange={(e) => setReactionTime(e.target.value)}
              placeholder="0.015"
            />
          </div>
          <div>
            <label className="label">Dial-In (for bracket)</label>
            <input
              type="number"
              step="0.001"
              className="input"
              value={dialIn}
              onChange={(e) => setDialIn(e.target.value)}
              placeholder="9.500"
            />
          </div>
        </div>

        <div className="mb-4">
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 'var(--space-3)' }}>
            <h3 className="label" style={{ margin: 0 }}>Environment</h3>
            <div>
              <input
                ref={fileInputRef}
                type="file"
                accept=".csv"
                onChange={handleImportWeatherCsv}
                style={{ display: 'none' }}
              />
              <button
                type="button"
                onClick={() => fileInputRef.current?.click()}
                className="btn btn-secondary"
                style={{ fontSize: '0.875rem', padding: 'var(--space-2) var(--space-3)' }}
              >
                Import Weather CSV
              </button>
            </div>
          </div>
          <EnvironmentForm value={env} onChange={setEnv} />
        </div>

        <button
          onClick={handleComputeBaseline}
          className="btn btn-full mb-4"
          disabled={baselineLoading}
        >
          {baselineLoading ? 'Computing...' : 'Compute Baseline'}
        </button>

        {baselineResult && (
          <div className="card card-compact" style={{ backgroundColor: 'var(--color-surface)' }}>
            <h3 className="mb-3" style={{ fontSize: '1rem', fontWeight: '600' }}>
              Baseline Prediction
            </h3>
            <div className="grid grid-2 gap-4">
              <div>
                <div className="text-muted" style={{ fontSize: '0.875rem' }}>
                  ET
                </div>
                <div style={{ fontSize: '1.5rem', fontWeight: 'bold' }}>
                  {baselineResult.baseET_s.toFixed(3)} s
                </div>
              </div>
              <div>
                <div className="text-muted" style={{ fontSize: '0.875rem' }}>
                  MPH
                </div>
                <div style={{ fontSize: '1.5rem', fontWeight: 'bold' }}>
                  {baselineResult.baseMPH.toFixed(2)} mph
                </div>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Section B: Run Completion (Optional) */}
      {baselineResult && (
        <div className="card mb-6">
          <h2 className="mb-4" style={{ fontSize: '1.25rem', color: 'var(--color-text)' }}>
            B) Run Completion (Optional)
          </h2>
          <p className="text-muted mb-4" style={{ fontSize: '0.9rem' }}>
            If you lifted early, estimate the final ET from a partial run.
          </p>

          {!tierFeatures.runCompletion && !tierFeatures.basicSim ? (
            <PeekCard
              title="Run Completion"
              tier="JUNIOR"
              description="Estimate final ET from partial runs. Upgrade to Racer for 60' completion, or Pro for all splits."
              onLearnMore={() => alert('Upgrade to unlock Run Completion')}
            />
          ) : (
            <>
              {completionError && (
                <div className="error mb-4">
                  <p style={{ margin: 0 }}>{completionError}</p>
                </div>
              )}

              <div className="grid grid-3 gap-4 mb-4">
            <div>
              <label className="label" htmlFor="splitDistance">
                Last WOT Split
              </label>
              <select
                id="splitDistance"
                className="input"
                value={splitDistance}
                onChange={(e) => setSplitDistance(parseInt(e.target.value))}
                style={{ cursor: 'pointer' }}
              >
                {availableSplits.map((d) => (
                  <option key={d} value={d}>
                    {d} ft
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="label" htmlFor="splitTime">
                Time at Split (s) *
              </label>
              <input
                id="splitTime"
                type="number"
                step="0.001"
                className="input"
                value={splitTime}
                onChange={(e) => setSplitTime(e.target.value)}
                placeholder="6.800"
              />
            </div>
            <div>
              <label className="label" htmlFor="splitMph">
                MPH at Split
              </label>
              <input
                id="splitMph"
                type="number"
                step="0.01"
                className="input"
                value={splitMph}
                onChange={(e) => setSplitMph(e.target.value)}
                placeholder="105.50"
              />
            </div>
          </div>

          <button onClick={handleCompleteRun} className="btn btn-full mb-4">
            Complete Run
          </button>

          {completionResult && (
            <div className="card card-compact" style={{ backgroundColor: 'var(--color-surface)' }}>
              <h3 className="mb-3" style={{ fontSize: '1rem', fontWeight: '600' }}>
                Completed ET Estimate
              </h3>
              <div className="grid grid-3 gap-4">
                <div>
                  <div className="text-muted" style={{ fontSize: '0.875rem' }}>
                    ET
                  </div>
                  <div style={{ fontSize: '1.5rem', fontWeight: 'bold' }}>
                    {completionResult.et_s.toFixed(3)} s
                  </div>
                </div>
                <div>
                  <div className="text-muted" style={{ fontSize: '0.875rem' }}>
                    Method
                  </div>
                  <div style={{ fontSize: '1rem', fontWeight: '500' }}>
                    {completionResult.method}
                  </div>
                </div>
                <div>
                  <div className="text-muted" style={{ fontSize: '0.875rem' }}>
                    Confidence
                  </div>
                  <div style={{ fontSize: '1rem', fontWeight: '500' }}>
                    {(completionResult.confidence * 100).toFixed(0)}%
                  </div>
                </div>
              </div>
            </div>
          )}
            </>
          )}
        </div>
      )}

      {/* Section C: Timing Splits */}
      {baselineResult && (
        <div className="card mb-6">
          <h2 className="mb-4" style={{ fontSize: '1.25rem', color: 'var(--color-text)' }}>
            C) Timing Data
          </h2>
          
          <div className="grid gap-4 mb-4" style={{ gridTemplateColumns: 'repeat(5, 1fr)' }}>
            <div>
              <label className="label">60 ft</label>
              <input type="number" step="0.001" className="input" value={sixtyFt} onChange={(e) => setSixtyFt(e.target.value)} placeholder="1.250" />
            </div>
            <div>
              <label className="label">330 ft</label>
              <input type="number" step="0.001" className="input" value={threeThirtyFt} onChange={(e) => setThreeThirtyFt(e.target.value)} placeholder="3.500" />
            </div>
            <div>
              <label className="label">1/8 ET</label>
              <input type="number" step="0.001" className="input" value={eighthET} onChange={(e) => setEighthET(e.target.value)} placeholder="6.800" />
            </div>
            <div>
              <label className="label">1/8 MPH</label>
              <input type="number" step="0.01" className="input" value={eighthMPH} onChange={(e) => setEighthMPH(e.target.value)} placeholder="105.5" />
            </div>
            {raceLength === 'QUARTER' && (
              <div>
                <label className="label">1000 ft</label>
                <input type="number" step="0.001" className="input" value={thousandFt} onChange={(e) => setThousandFt(e.target.value)} placeholder="7.600" />
              </div>
            )}
          </div>

          <div className="grid grid-2 gap-4 mb-4">
            <div>
              <label className="label" htmlFor="actualET">
                {raceLength === 'QUARTER' ? '1/4 Mile' : '1/8 Mile'} ET (s) *
              </label>
              <input
                id="actualET"
                type="number"
                step="0.001"
                className="input"
                value={actualET}
                onChange={(e) => setActualET(e.target.value)}
                placeholder={raceLength === 'QUARTER' ? '11.500' : '6.800'}
                required
              />
            </div>
            <div>
              <label className="label" htmlFor="actualMPH">
                {raceLength === 'QUARTER' ? '1/4 Mile' : '1/8 Mile'} MPH
              </label>
              <input
                id="actualMPH"
                type="number"
                step="0.01"
                className="input"
                value={actualMPH}
                onChange={(e) => setActualMPH(e.target.value)}
                placeholder={raceLength === 'QUARTER' ? '120.50' : '105.50'}
              />
            </div>
          </div>
        </div>
      )}

      {/* Section D: Opponent Information */}
      {baselineResult && (
        <div className="card mb-6">
          <h2 className="mb-4" style={{ fontSize: '1.25rem', color: 'var(--color-text)' }}>
            D) Opponent Information (Optional)
          </h2>
          
          <div className="grid grid-2 gap-4 mb-4">
            <div>
              <label className="label">Opponent Name</label>
              <input type="text" className="input" value={opponentName} onChange={(e) => setOpponentName(e.target.value)} placeholder="John Doe" />
            </div>
            <div>
              <label className="label">Opponent Dial-In</label>
              <input type="number" step="0.001" className="input" value={opponentDialIn} onChange={(e) => setOpponentDialIn(e.target.value)} placeholder="9.500" />
            </div>
          </div>
          
          <div className="grid gap-4 mb-4" style={{ gridTemplateColumns: 'repeat(3, 1fr)' }}>
            <div>
              <label className="label">Opponent RT</label>
              <input type="number" step="0.001" className="input" value={opponentRT} onChange={(e) => setOpponentRT(e.target.value)} placeholder="0.015" />
            </div>
            <div>
              <label className="label">Opponent ET</label>
              <input type="number" step="0.001" className="input" value={opponentET} onChange={(e) => setOpponentET(e.target.value)} placeholder="9.520" />
            </div>
            <div>
              <label className="label">Opponent MPH</label>
              <input type="number" step="0.01" className="input" value={opponentMPH} onChange={(e) => setOpponentMPH(e.target.value)} placeholder="142.50" />
            </div>
          </div>

          {/* Margin of Victory Display */}
          {dialIn && reactionTime && actualET && opponentDialIn && opponentRT && opponentET && (
            <div className="card card-compact" style={{ backgroundColor: 'var(--color-surface)', marginTop: 'var(--space-4)' }}>
              <h3 className="mb-3" style={{ fontSize: '1rem', fontWeight: '600', color: '#10b981' }}>
                Margin of Victory
              </h3>
              {(() => {
                const mov = calculateMOV(
                  { dialIn: parseFloat(dialIn), reactionTime: parseFloat(reactionTime), et: parseFloat(actualET) },
                  { dialIn: parseFloat(opponentDialIn), reactionTime: parseFloat(opponentRT), et: parseFloat(opponentET) }
                );
                const youWon = mov.winner === 'racer1';
                const outcome = describeRaceOutcome(mov, 'You', opponentName || 'Opponent');
                return (
                  <div>
                    <div style={{ fontSize: '1.5rem', fontWeight: 'bold', color: youWon ? '#10b981' : '#ef4444' }}>
                      {youWon ? 'WIN' : 'LOSS'} by {formatMOV(mov)}
                    </div>
                    <div style={{ fontSize: '0.9rem', color: 'var(--color-muted)', marginTop: 'var(--space-2)' }}>
                      {outcome}
                    </div>
                  </div>
                );
              })()}
            </div>
          )}
        </div>
      )}

      {/* Section E: Notes & Save */}
      {baselineResult && (
        <div className="card mb-6">
          <h2 className="mb-4" style={{ fontSize: '1.25rem', color: 'var(--color-text)' }}>
            E) Save Run
          </h2>

          {saveError && (
            <div className="error mb-4">
              <p style={{ margin: 0 }}>{saveError}</p>
            </div>
          )}

          <div className="mb-4">
            <label className="label" htmlFor="notes">
              Notes
            </label>
            <textarea
              id="notes"
              className="input"
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              placeholder="Track conditions, setup changes, etc."
              rows={4}
              style={{ resize: 'vertical', fontFamily: 'inherit' }}
            />
          </div>

          <div className="flex gap-4">
            <button
              onClick={handleSaveRun}
              className="btn btn-full"
              disabled={saving}
            >
              {saving ? 'Saving...' : 'Save Run'}
            </button>
            <button
              type="button"
              className="btn btn-secondary btn-full"
              onClick={() => navigate('/history')}
              disabled={saving}
            >
              Cancel
            </button>
          </div>
        </div>
      )}
    </Page>
  );
}

export default Log;
